    step("负数:int32 / int64 把 -1 当 64 位补码,占 10 个字节(ff ff ff ff ff ff ff ff ff 01);sint32 / sint64 先做 ZigZag 映射(0→0、-1→1、1→2、-2→3、-64→127、64→128),-1 只要 1 字节(01)。-64 到 63 在 sint 里 1 字节,在 int32 里负数都是 10 字节;-1000 在 sint 里 2 字节,在 int32 里 10 字节;int32 最小值 -2147483648 在 sint32 里 5 字节。手写的 ZigZag 编码与库一致。", t=tl(S(2)), done=lidx(S(2), '        -1 '), mark=lidx(S(2), '-2147483648'), b=bars([['-1 用 int32', 10, '10'], ['-1 用 sint32', 1, '1'], ['-1000 用 int32', 10, '10'], ['-1000 用 sint32', 2, '2']], 11, mark=[0, 2], done=[1, 3]), kv=KV([['int32 的 -1', '10 字节(64 位补码)'], ['sint32 的 -1', '1 字节(ZigZag 后是 1)'], ['ZigZag', '0→0,-1→1,1→2,-2→3']], ['sint32 的 -1'])),
    step("数据分布决定大小(各 10 万个整数):小值 0–100,varint 100000 字节(每个 1.00)、定长 4 字节 400000、JSON 数组 291117、MessagePack 数组 100005;0–10000 均匀值,varint 198728(1.99),MessagePack 296173;任意 32 位整数,varint 493697(4.94)反而比定长 4 字节(400000)大;Unix 时间戳(大约 1.7×10^9),varint 500000(每个 5 字节)大于定长 4 字节的 400000;幂律分布 varint 100319(1.00)。数值小而集中,varint 占优;数值大,varint 反而比定长多。", t=tl(S(3)), done=lidx(S(3), '小值 0–100'), mark=lidx(S(3), 'Unix 时间戳'), b=bars([['小值:varint', 100000, '100000'], ['小值:定长 4', 400000, '400000'], ['时间戳:varint', 500000, '500000'], ['时间戳:定长 4', 400000, '400000']], 500000, done=[0], mark=[2]), kv=KV([['小值 0–100', 'varint 1.00 字节/个'], ['任意 32 位整数', 'varint 4.94 字节/个 > 定长 4'], ['时间戳', 'varint 5 字节/个 > 定长 4']], ['时间戳'])),
    step("差分编码(5 万条 timeseries 的 ts 列):原始值 varint 250000 字节(zstd-3 后 46185,gzip-6 后 69627),原始值定长 8 字节 400000(zstd 后 50959,gzip 后 75842),差分 + ZigZag varint 只要 50004 字节(每个 1 字节),zstd 后 9005、gzip 后 7383;差分的差分 + ZigZag varint 50004,zstd 后 9098。相邻差值只有 1 和 2 两种,先差分再压缩比直接压缩原始值小 5 倍以上;JSON 文本是 550001 字节。预处理让数据变得“有规律”,压缩器才吃得上。", t=tl(S(4)), done=lidx(S(4), '差分 + ZigZag varint'), mark=lidx(S(4), '原始值 varint'), b=bars([['原始值 varint → zstd', 46185, '46185'], ['原始值定长 8 → zstd', 50959, '50959'], ['差分 + ZigZag → zstd', 9005, '9005'], ['差分 + ZigZag → gzip', 7383, '7383']], 52000, mark=[0, 1], done=[2, 3]), kv=KV([['原始值 varint', '250000 字节 → zstd 46185'], ['差分 + ZigZag varint', '50004 字节 → zstd 9005,gzip 7383'], ['差值的取值', '只有 1 和 2 两种']], ['差分 + ZigZag varint'])),
